/// <reference types="bun-types" />
// ============ Unit tests — crypto-field.ts MFA backward compatibility ============
// Phase 3 deliverable (item 2 of the Phase-3 kickoff): proves the extraction
// of encryptSecret/decryptSecret from totp.ts into crypto-field.ts preserves
// MFA's bit-for-bit behavior. The fixture ciphertext below was generated by
// the PRE-refactor totp.ts (captured before the shim was applied) using
// HRM_MFA_KEY = the example value from .env.example. If decryptSecret(fixture)
// ever stops returning the original plaintext, this test fails — the
// refactor regressed MFA and a user's existing enrolments would lock out.
//
// Camera credentials also exercise crypto-field.ts (with context="cameras::v1")
// to verify domain isolation: the same env key derives DIFFERENT AES-256 keys
// for MFA vs cameras, so a breach of one domain does not expose the other.
import { test, expect, describe, beforeAll, afterAll } from "bun:test"
import {
  encryptField, decryptField, decryptFieldMfaLegacy,
  fieldKeyConfigured, mfaSecretNeedsReencrypt,
} from "@/hrm-server/crypto-field"
import {
  encryptSecret, decryptSecret, mfaKeyConfigured, needsReencrypt,
} from "@/hrm-server/totp"

// ---------- fixtures ----------

/** HRM_MFA_KEY value used to generate the fixture ciphertext below.
 *  PROVENANCE (L-4): this is the key that shipped in the received build's
 *  .env / .env.example — one of the KNOWN_LEAKED_MFA_KEYS instrumentation.ts
 *  refuses to boot with. It is embedded here ONLY because the back-compat
 *  fixture ciphertext was generated under it; it must NEVER be configured on
 *  a real deployment (boot fails closed if it is). */
const FIXTURE_HRM_MFA_KEY = "4bc878a3825fedd92f2da05a6e33938f281f29d2a4ddcbd14fab5dc74e1cf27b" // scan-secrets:allow-fixture — L-4 provenance: the pre-refactor ciphertext fixture below was generated under this now-dead value; the boot guard refuses it on any real deployment

/** Plaintext that was encrypted by the PRE-refactor encryptSecret(). */
const FIXTURE_PLAINTEXT = "phase3-mfa-backcompat-fixture"

/** Ciphertext captured from the pre-refactor totp.ts on 2026-09-26 by
 *  running encryptSecret(FIXTURE_PLAINTEXT) with HRM_MFA_KEY=FIXTURE_HRM_MFA_KEY.
 *  Format: "v2:<ivHex>.<tagHex>.<encHex>" — the "v2:" prefix marks env-keyed. */
const FIXTURE_CIPHERTEXT = "v2:11db59b68efec290287390c4.65687347196983c5047a51339282bb33.2f67b8b4b3fc61faaa8c88daa8592a9a1b5179ce03648e15c4ce31163a"

// ---------- env setup / teardown ----------

const SAVED_KEY = process.env.HRM_MFA_KEY

beforeAll(() => {
  process.env.HRM_MFA_KEY = FIXTURE_HRM_MFA_KEY
})

afterAll(() => {
  if (SAVED_KEY === undefined) delete process.env.HRM_MFA_KEY
  else process.env.HRM_MFA_KEY = SAVED_KEY
})

// ---------- MFA backward-compat: the bit-for-bit test ----------

describe("crypto-field MFA backward compatibility (Phase 3 item 2)", () => {
  test("decryptSecret(pre-refactor ciphertext) returns the original plaintext", () => {
    // This is THE bit-for-bit test: if it fails, the refactor broke MFA and
    // every existing user enrolment locked out. Do not weaken this assertion.
    const plain = decryptSecret(FIXTURE_CIPHERTEXT)
    expect(plain).toBe(FIXTURE_PLAINTEXT)
  })

  test("decryptField(stripped-v2-prefix, \"mfa::v2\") also returns the plaintext", () => {
    // Direct crypto-field call — proves the underlying primitive is intact
    // and that the "mfa::v2" context derives the SAME key as the pre-refactor
    // totp.ts deriveKey() (which used salt "finix-mart-hrm::mfa::v2::" + envKey).
    const body = FIXTURE_CIPHERTEXT.slice("v2:".length)
    expect(decryptField(body, "mfa::v2")).toBe(FIXTURE_PLAINTEXT)
  })

  test("encryptSecret(plain) → decryptSecret(ct) round-trips", () => {
    const ct = encryptSecret(FIXTURE_PLAINTEXT)
    expect(ct).toMatch(/^v2:[0-9a-f]+\.[0-9a-f]+\.[0-9a-f]+$/)
    expect(decryptSecret(ct)).toBe(FIXTURE_PLAINTEXT)
  })

  test("encryptSecret produces a DIFFERENT ciphertext each call (random IV)", () => {
    // The IV is 12 random bytes — two encrypts of the same plaintext must
    // produce different ciphertexts (semantic security).
    const a = encryptSecret("same-plaintext")
    const b = encryptSecret("same-plaintext")
    expect(a).not.toBe(b)
    expect(decryptSecret(a)).toBe("same-plaintext")
    expect(decryptSecret(b)).toBe("same-plaintext")
  })

  test("mfaKeyConfigured() is true when HRM_MFA_KEY is set", () => {
    expect(mfaKeyConfigured()).toBe(true)
    expect(fieldKeyConfigured()).toBe(true)
  })

  test("needsReencrypt(v2 ciphertext) returns false — already migrated", () => {
    expect(needsReencrypt(FIXTURE_CIPHERTEXT)).toBe(false)
    expect(mfaSecretNeedsReencrypt(FIXTURE_CIPHERTEXT)).toBe(false)
  })
})

// ---------- MFA legacy fallback (pre-H-8 hardcoded key) ----------

describe("MFA legacy fallback (pre-H-8 secrets written under the hardcoded key)", () => {
  test("decryptFieldMfaLegacy handles a legacy-format ciphertext", () => {
    // Construct a legacy (unprefixed) ciphertext using the legacy fixed key.
    // We can't easily generate one via encryptSecret (which always prepends v2:),
    // so we craft one directly via crypto-field's underlying primitive.
    const crypto = require("crypto")
    const MFA_LEGACY_SALT = "finix-mart-hrm::mfa::v1"
    const legacyKey = crypto.createHash("sha256").update(MFA_LEGACY_SALT).digest()
    const iv = crypto.randomBytes(12)
    const cipher = crypto.createCipheriv("aes-256-gcm", legacyKey, iv)
    const enc = Buffer.concat([cipher.update("legacy-test-secret", "utf8"), cipher.final()])
    const tag = cipher.getAuthTag()
    const legacyCt = `${iv.toString("hex")}.${tag.toString("hex")}.${enc.toString("hex")}`

    // decryptFieldMfaLegacy should decode it
    expect(decryptFieldMfaLegacy(legacyCt)).toBe("legacy-test-secret")

    // decryptSecret on the SAME legacy ct (with env key set) should also work
    // via the legacy-first-fallback path
    expect(decryptSecret(legacyCt)).toBe("legacy-test-secret")

    // needsReencrypt(legacy ct) returns true when env key is set (should migrate)
    expect(needsReencrypt(legacyCt)).toBe(true)
    expect(mfaSecretNeedsReencrypt(legacyCt)).toBe(true)
  })

  test("decryptSecret on a corrupt ciphertext throws cleanly", () => {
    expect(() => decryptSecret("garbage")).toThrow()
    expect(() => decryptSecret("v2:not.enough")).toThrow()
    expect(() => decryptSecret("")).toThrow()
  })
})

// ---------- Camera credentials + domain isolation ----------

describe("crypto-field for camera credentials (context=\"cameras::v1\")", () => {
  test("encryptField → decryptField round-trips for cameras", () => {
    const ct = encryptField('{"appKey":"abc","appSecret":"xyz"}', "cameras::v1")
    expect(ct).toMatch(/^[0-9a-f]+\.[0-9a-f]+\.[0-9a-f]+$/)
    // NO "v2:" prefix — cameras use the encryptionKeyVersion column instead
    expect(ct.startsWith("v2:")).toBe(false)
    expect(decryptField(ct, "cameras::v1")).toBe('{"appKey":"abc","appSecret":"xyz"}')
  })

  test("MFA and cameras derive DIFFERENT keys (domain isolation)", () => {
    // Encrypt a plaintext as a camera credential
    const camCt = encryptField("shared-test-plaintext", "cameras::v1")

    // Attempt to decrypt it as an MFA secret (prepend "v2:" so decryptSecret
    // takes the v2 path). GCM auth tag check MUST fail — proves the derived
    // keys are different.
    expect(() => decryptSecret("v2:" + camCt)).toThrow()
  })

  test("decryptField with the WRONG context throws (GCM tag mismatch)", () => {
    const camCt = encryptField("camera-only", "cameras::v1")
    expect(() => decryptField(camCt, "mfa::v2")).toThrow()
    expect(() => decryptField(camCt, "wrong-context")).toThrow()
  })

  test("encryptField refuses when HRM_MFA_KEY is unset (fail-closed for new writes)", () => {
    const saved = process.env.HRM_MFA_KEY
    delete process.env.HRM_MFA_KEY
    try {
      expect(() => encryptField("test", "cameras::v1")).toThrow()
      expect(fieldKeyConfigured()).toBe(false)
      expect(mfaKeyConfigured()).toBe(false)
    } finally {
      process.env.HRM_MFA_KEY = saved
    }
  })
})
